'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const titles = {opportunities:'Opportunities',studio:'Content studio',approvals:'Review queue',calendar:'Calendar',knowledge:'Project knowledge',campaign:'Browser campaign',analytics:'Analytics',system:'System & audit log'};
const kinds = {post:'Short original post',update:'Project update',education:'Educational thread',opinion:'Evidence-backed opinion',question:'Community question',meme:'Meme & image brief',reply:'Conversation reply',quote:'Quote commentary'};
const tones = {dry:'Dry humor',sarcastic:'Sarcastic',absurd:'Absurd',community:'Community-native',straightforward:'Straightforward'};
let state={view:'opportunities',filter:'relevant',health:null,profile:null,drafts:[],opportunities:[],browser:null,campaignSettings:null,selected:null,context:null,onboardingShown:false};
let toastTimer;
function toast(message,error=false){ const el=$('#toast'); el.textContent=message; el.className=error?'error':'';el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,error?10000:4500); }
async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:body!==undefined?{'Content-Type':'application/json'}:{},body:body!==undefined?JSON.stringify(body):undefined});let result;try{result=await r.json();}catch{throw Error('Server did not return JSON. Check the process and authentication.');}if(!r.ok)throw Error((result.detail||'Request failed')+(result.errors?' · '+result.errors.map(e=>e.field+': '+e.message).join('; '):''));return result;}
function action(name,label,extra='',cls=''){return `<button class="${esc(cls)}" data-action="${esc(name)}" ${extra}>${label}</button>`;}
function badge(text,cls=''){return `<span class="badge ${esc(cls)}">${esc(text)}</span>`;}
function date(ts){return new Date(ts*1000).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});}
function dtInput(ts){const d=new Date(ts*1000);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function options(values,selected){return Object.entries(values).map(([k,v])=>`<option value="${esc(k)}" ${k===selected?'selected':''}>${esc(v)}</option>`).join('');}
function heading(title,sub,buttons='',eyebrow='YOUR COMMUNITY, THOUGHTFULLY'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="button-row">${buttons}</div></div>`;}
function empty(title,description){return `<div class="empty"><strong>${title}</strong>${description}</div>`;}
function stat(title,value,note,icon='↗'){return `<div class="stat"><div class="stat-title">${title}<span class="stat-icon">${icon}</span></div><strong>${esc(value)}</strong><small>${note}</small></div>`;}
function field(name,label,value='',type='text',wide=false){return `<div class="${wide?'wide':''}"><label for="${esc(name)}">${label}</label>${type==='textarea'?`<textarea id="${esc(name)}" name="${esc(name)}">${esc(value)}</textarea>`:`<input id="${esc(name)}" name="${esc(name)}" type="${esc(type)}" value="${esc(value)}">`}</div>`;}
function list(value){return value.split('\n').map(s=>s.trim()).filter(Boolean);}
function updateShell(){
  const h=state.health,p=state.profile.profile;
  $('#workspace-name').innerHTML=`${esc(p.name.slice(0,26))}<small>@${esc(p.account)}</small>`;
  $('.workspace .avatar').textContent=p.name.split(' ').slice(0,2).map(s=>s[0]).join('').toUpperCase();
  $('#mode-badge').textContent=h.mode==='demo'?'FICTIONAL DEMO':h.mode==='browser'?'BROWSER CAMPAIGN':'MANUAL WORKFLOW';
  $('#mode-banner').textContent=h.stopped?'Emergency stop is active. Scheduled and browser campaign work is paused. In-flight requests cannot be undone.':h.mode==='demo'?'Fictional demo data · simulations only · nothing is connected to X or published.':h.mode==='browser'?`Browser campaign · ${state.browser?.dry_run?'dry run previews only':'live UI posting enabled'} · ${state.browser?.running?'worker running':'worker stopped'}.`:'Manual workflow · approved originals become export-ready at their scheduled time.';
  $('#mode-banner').classList.toggle('stopped',h.stopped);
  $('#stop-button').textContent=h.stopped?'▶ Resume queue':'■ Emergency stop';
  $('#opportunity-count').textContent=state.opportunities.filter(o=>o.ranking.appropriate).length;
  $('#review-count').textContent=state.drafts.filter(d=>d.status==='draft').length;
  $('#campaign-count').textContent=(state.browser?.counts?.queued||0)+(state.browser?.counts?.previewed||0);
  $$('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===state.view));
  $('#breadcrumb').textContent=titles[state.view];
}
async function refresh(){const [health,profile,drafts,opportunities,browser,campaignSettings]=await Promise.all([api('/health'),api('/profile'),api('/drafts'),api('/opportunities'),api('/browser'),api('/campaign-settings')]);Object.assign(state,{health,profile,drafts,opportunities,browser,campaignSettings});updateShell();await render();if(health.mode==='browser'&&!campaignSettings.onboarding_complete&&!state.onboardingShown){state.onboardingShown=true;setTimeout(()=>openCampaignSetup(true),0);}}
async function render(){
  const view=state.view;
  const renderers={opportunities:renderOpportunities,studio:renderStudio,approvals:renderApprovals,calendar:renderCalendar,knowledge:renderKnowledge,campaign:renderCampaign,analytics:renderAnalytics,system:renderSystem};
  const html=await renderers[view]();
  if(state.view===view)$('#content').innerHTML=html;
}
function renderOpportunities(){
  const good=state.opportunities.filter(o=>o.ranking.appropriate),shown=state.filter==='all'?state.opportunities:good;
  const pending=state.drafts.filter(d=>d.status==='draft').length;
  return heading('Find your next good conversation.','Start with something useful to say. The right people will notice.',action('import','↓ Import conversations','','small')+action('refresh','↻ Refresh','','small'))+
  `<div class="stats">${stat('Worth a closer look',good.length,'Ranked by relevance & context','◎')}${stat('Drafts to review',pending,'Your voice. Your final say.','✎')}${stat('Originals scheduled',state.drafts.filter(d=>d.status==='scheduled').length,'Individually approved only','▦')}${stat('Daily posting limit',state.health.limits.daily,`${state.health.limits.gap_minutes} min between attempts`,'◷')}</div>
  <div class="columns"><section><div class="section-bar"><h2>Conversation opportunities <span class="subtle">/ ${shown.length}</span></h2><div class="filters">${action('filter','Relevant',`data-filter="relevant"`,state.filter==='relevant'?'active':'')}${action('filter','All imported',`data-filter="all"`,state.filter==='all'?'active':'')}</div></div>
  ${shown.map(o=>`<article class="opportunity"><div class="card-top"><span class="avatar">${esc(o.author.slice(0,2).toUpperCase())}</span><div><strong>${esc(o.author)}</strong><br><small>@${esc(o.author)} · ${date(o.posted_at)}</small></div>${badge(o.ranking.appropriate?o.ranking.score+' / 100 relevance':'Excluded',o.ranking.appropriate?'':'amber')}</div><p class="post-text">${esc(o.text)}</p><a class="original-link" href="${esc(o.url)}" target="_blank" rel="noopener noreferrer">View original post ↗${o.fictional?' · fictional link':''}</a><div class="reason">${o.ranking.reasons.map(esc).join(' · ')}</div><p class="meta">${esc(o.context)}${o.fictional?' · FICTIONAL SAMPLE':''}</p><div class="card-footer"><span class="meta">${o.replies} public replies · ${o.inbound?'Engaging with our account':'Public conversation'}<br>Retrieved content is untrusted data.</span><div class="button-row">${action('suggest','Draft a reply ↗',`data-id="${esc(o.id)}" data-kind="reply" ${!o.ranking.appropriate?'disabled':''}`,'small primary')}${action('suggest','Quote',`data-id="${esc(o.id)}" data-kind="quote" ${!o.ranking.appropriate?'disabled':''}`,'small')}</div></div></article>`).join('')||empty('Room for a good conversation','Import permitted public post data or update your project keywords.')}</section>
  <aside class="aside-column"><div class="side-panel"><div class="eyebrow">THE GARDEN RULE</div><h3>Contribute first.<br>Promote when it fits.</h3><p>A question answered well is worth more than a hundred drive-by replies.</p><div class="note-line"><strong>01 &nbsp; Read the room</strong>Check the original context before responding.</div><div class="note-line"><strong>02 &nbsp; Add something</strong>A useful detail. An honest answer. A good joke.</div><div class="note-line"><strong>03 &nbsp; Keep it human</strong>Use verified project facts and one account.</div></div><div class="side-panel"><div class="eyebrow">YOUR GUARDRAILS</div><div class="status-row"><span>X delivery</span>${badge(state.health.mode==='browser'?'Local browser':'Unavailable',state.health.mode==='browser'?'':'amber')}</div><div class="status-row"><span>Authorization</span>${badge(state.health.mode==='browser'?'Campaign profile':'Per draft')}</div><div class="status-row"><span>Quiet hours</span><strong>${state.health.limits.quiet_hours}</strong></div><p class="no-margin">${esc(state.health.timezone)} · no automated DMs or account rotation.</p></div></aside></div>`;
}
function draftCard(d){const b=d.body;return `<article class="card draft-card"><div class="section-bar"><span class="eyebrow no-margin">${esc(kinds[b.kind])}</span>${badge(d.status,d.review.blockers.length?'amber':'')}</div><p class="post-text">${esc(b.text)}</p><div class="meta">${esc(tones[b.tone])} · ${esc(b.topic)} · ${d.review.weighted_length}/280${b.fictional?' · FICTIONAL':''}</div><div class="card-footer"><span class="meta">${d.review.blockers.length?d.review.blockers.length+' review blocker(s)':d.status==='draft'?'Ready for human review':'Approval is tied to exact content'}</span>${action('edit','Open draft →',`data-id="${d.id}"`,'small')}</div></article>`;}
function generator(){return `<form id="generator" class="generator"><h2>A few different ways to say it.</h2><p>Use the project knowledge as a starting point. Review every claim and make the words your own.</p>${state.context?`<div class="notice">Selected conversation: @${esc(state.context.author)}. Suggestions will retain this context. ${action('clear-context','Clear','','small')}</div>`:''}<div class="form-grid"><div><label for="kind">Format</label><select id="kind" name="kind">${options(kinds,state.context?.kind||'post')}</select></div><div><label for="tone">Tone</label><select id="tone" name="tone">${options(tones,'dry')}</select></div>${field('topic','One clear idea','community')}<button class="primary" type="submit">✧ Generate 3 options</button></div></form>`;}
function renderStudio(){const drafts=state.drafts.filter(d=>d.status!=='discarded');return heading('Make something worth sharing.','A strong hook. One clear idea. A voice that sounds like you.',action('new-draft','+ Write a draft','','small'))+generator()+`<div class="section-bar"><h2>Your drafts <span class="subtle">/ ${drafts.length}</span></h2><span class="subtle">${state.health.model.provider==='template'?'Offline template engine · $0':'Configured model · budget enforced'}</span></div><div class="draft-grid">${drafts.map(draftCard).join('')}</div>`+(drafts.length?'':empty('Your next idea starts here','Generate options above, or write a draft from scratch.'));}
function renderApprovals(){const drafts=state.drafts.filter(d=>['draft','approved','ready','failed','uncertain'].includes(d.status));return heading('Good judgment is part of the process.','Review the content, the sources, and the context. Edits always invalidate approval.',action('refresh','↻ Refresh','','small'),'REVIEW BEFORE REACH')+`<div class="notice">Approve only after checking every factual claim. Automated checks catch common problems; they cannot establish that a claim is true.</div><div class="draft-grid">${drafts.map(draftCard).join('')}</div>`+(drafts.length?'':empty('Nothing waiting on you','New drafts and export-ready originals appear here.'));}
async function renderCalendar(){
  const jobs=await api('/calendar'),today=new Date(),days=[];
  for(let i=0;i<7;i++){const d=new Date(today);d.setDate(d.getDate()+i);days.push(d);}
  return heading('A little consistency goes a long way.','Only approved originals can be scheduled. Replies, quotes, threads, and images stay manual.',action('refresh','↻ Refresh','','small'),'PLAN WITH INTENTION')+
  `<div class="notice">Times below use your browser timezone (${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}). Quiet hours use ${esc(state.health.timezone)}. ${state.health.mode==='demo'?'Due posts produce fictional receipts.':'Due posts become export-ready; you publish them manually in X.'}</div><div class="calendar">${days.map((day,i)=>`<div class="day ${i===0?'today':''}"><span class="subtle">${day.toLocaleDateString(undefined,{weekday:'short'})}</span><div class="day-number">${day.getDate()}</div>${jobs.filter(j=>new Date(j.due_at*1000).toDateString()===day.toDateString()).map(j=>action('edit',`${new Date(j.due_at*1000).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}<br>${esc(JSON.parse(j.body).topic)} · ${esc(j.state)}`,`data-id="${j.draft_id}"`,'event')).join('')}</div>`).join('')}</div><div class="card"><h2>All scheduled work</h2><div class="table-scroll"><table class="list-table"><thead><tr><th>When</th><th>Topic</th><th>State</th><th>Attempts</th><th>Result</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${date(j.due_at)}</td><td>${action('edit',esc(JSON.parse(j.body).topic),`data-id="${j.draft_id}"`,'small')}</td><td>${badge(j.state,j.state==='uncertain'?'red':'')}</td><td>${j.attempts}</td><td>${esc(j.error||j.receipt||'Waiting')}</td></tr>`).join('')||'<tr><td colspan="5">No scheduled originals yet. Approve a draft, then choose a time.</td></tr>'}</tbody></table></div></div>`;
}
function factForm(f,index){return `<div class="fact" data-fact="${index}"><div class="fact-header"><strong>Knowledge item ${index+1}</strong><div>${badge(state.profile.fact_statuses?.[f.id]||f.classification,f.classification==='verified'?'':'amber')} ${action('remove-fact','Remove','','small')}</div></div><div class="form-grid">${field('fact-id-'+index,'Stable source ID',f.id)}<div><label for="fact-class-${index}">Classification</label><select id="fact-class-${index}" data-f="classification">${options({verified:'Verified fact',opinion:'Opinion',unverified:'Unverified information'},f.classification)}</select></div>${field('fact-days-'+index,'Stale after (days)',f.stale_after_days,'number')}${field('fact-text-'+index,'Claim or information',f.text,'textarea',true)}${field('fact-source-'+index,'Supporting source (HTTPS)',f.source,'url',true)}${field('fact-time-'+index,'Last verified (your local time)',f.verified_at?dtInput(f.verified_at):'','datetime-local',true)}</div></div>`;}
function renderKnowledge(){const p=state.profile.profile;return heading('Keep the facts close.','One shared source of truth for your project, voice, and boundaries.','','KNOW WHAT YOU STAND FOR')+`<form id="knowledge-form"><div class="card"><div class="section-bar"><h2>Project identity</h2>${badge(p.fictional?'Fictional example':'User-provided project',p.fictional?'amber':'')}</div><div class="form-grid">${field('name','Project name',p.name)}${field('account','Clearly identified X account (without @)',p.account)}${field('ticker','Ticker',p.ticker)}${field('chain','Chain',p.chain)}${field('contract_address','Verified contract address (leave empty if unknown)',p.contract_address)}${field('contract_fact_id','Contract verification source ID',p.contract_fact_id)}${field('official_links','Official HTTPS links — one per line',p.official_links.join('\n'),'textarea',true)}${field('disclosure','Affiliation disclosure included in every draft',p.disclosure,'text',true)}</div><label class="check-label"><input type="checkbox" id="fictional" ${p.fictional?'checked':''}>This is a fictional/sample project. Keep checked until the project details and sources are real.</label></div>
  <div class="card"><h2>Audience & voice</h2><div class="form-grid">${field('audience','Target audience',p.audience,'textarea',true)}${field('voice','Voice preferences',p.voice,'textarea',true)}${field('slang','Community slang — one per line',p.slang.join('\n'),'textarea')}${field('jokes','Recurring jokes — one per line',p.jokes.join('\n'),'textarea')}${field('competitors','Competitors — one per line',p.competitors.join('\n'),'textarea')}${field('keywords','Research keywords — one per line',p.keywords.join('\n'),'textarea')}${field('monitored_accounts','Relevant public accounts — one per line, no @',p.monitored_accounts.join('\n'),'textarea')}${field('forbidden_claims','Claims never to make — one per line',p.forbidden_claims.join('\n'),'textarea')}${field('good_examples','Good examples — one per line',p.good_examples.join('\n'),'textarea')}${field('bad_examples','Bad examples — one per line',p.bad_examples.join('\n'),'textarea')}</div></div>
  <div class="card"><div class="section-bar"><h2>Facts, opinions & uncertainties</h2>${action('add-fact','+ Add knowledge item','','small')}</div><p class="subtle">Features, token mechanics, milestones, and address verification belong here. A verified fact needs a source and a recent verification date. Source URLs are stored; the app does not fetch or authenticate them.</p><div id="facts">${p.facts.map(factForm).join('')}</div></div><div class="notice warning">Saving project knowledge revokes existing approvals and pending schedules. Delivered posts and uncertain outcomes remain preserved.</div><button type="submit" class="primary">Save project knowledge</button></form>`;}
async function renderAnalytics(){const a=await api('/analytics'),w=a.weekly;state.analytics=a;const val=k=>a.totals[k].total??'—';return heading('Learn from the conversation.','Measure useful engagement. Keep uncertainty visible.',action('weekly-export','↓ Weekly report','','small'),'LESS VOLUME. MORE VALUE.')+
  `<div class="stats">${stat('Meaningful replies',val('meaningful_replies'),a.totals.meaningful_replies.available_posts+' posts with data')}${stat('Profile visits',val('profile_visits'),a.totals.profile_visits.available_posts+' posts with data')}${stat('Qualified clicks',val('qualified_clicks'),a.totals.qualified_clicks.available_posts+' posts with data')}${stat('Comparable posts',w.comparable_posts,'Snapshots captured at 24–48 hours')}</div><div class="notice">${esc(w.assessment)}<br>${esc(w.measurement_window)} “—” means unavailable, never zero.</div>
  <div class="report-pair"><div class="card"><h2>This week's signals</h2><h3>Meaningful engagement observed</h3>${w.meaningful_engagement.map(r=>`<p class="subtle">${esc(r.topic)} · ${r.meaningful_replies} substantive replies ${action('edit','View',`data-id="${r.draft_id}"`,'small')}</p>`).join('')||'<p class="subtle">No comparable engagement measurements yet.</p>'}<h3>Lower observed response</h3>${w.underperformed.map(r=>`<p class="subtle">${esc(r.topic)} · ${r.meaningful_replies} substantive replies</p>`).join('')||'<p class="subtle">Collect data before interpreting performance.</p>'}<p class="field-note">Small samples can put the same post in both lists. These are counts, not evidence of causation.</p></div><div class="card"><h2>Experiments worth trying</h2><ol class="report-list">${w.experiments.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="field-note">Suggestions never change permissions, posting limits, or schedules.</p></div></div>
  <div class="card"><h2>Compare one variable at a time</h2><div class="button-row">${Object.keys(a.comparisons).map(k=>action('comparison',esc(k.replace('_',' ')),`data-dimension="${k}"`,'small')).join('')}</div><div id="comparison-table">${comparison(a,'topic')}</div></div>
  <div class="report-pair"><div class="card"><h2>Themes getting repetitive</h2>${w.repetitive_themes.map(t=>`<p>${esc(t.topic)} ${badge(t.drafts+' drafts')}</p>`).join('')||'<p class="subtle">No topic has three or more drafts this week.</p>'}</div><div class="card"><h2>Questions to keep listening for</h2><ul class="report-list">${w.community_questions.map(q=>`<li>${esc(q)}</li>`).join('')||'<li>No imported questions yet.</li>'}</ul></div></div>
  <div class="card"><div class="section-bar"><h2>Post measurements</h2>${action('metrics','+ Record metrics','','small')}</div><div class="table-scroll"><table class="list-table"><thead><tr><th>Post</th><th>Age</th><th>Impressions</th><th>Meaningful replies</th><th>Profile visits</th><th>Qualified clicks</th></tr></thead><tbody>${a.posts.map(r=>`<tr><td>${esc(r.body.topic)}<br>${badge(r.mode==='demo'?'Fictional simulation':'Manually recorded')}</td><td>${r.age_hours}h</td><td>${r.metrics.impressions??'—'}</td><td>${r.metrics.meaningful_replies??'—'}</td><td>${r.metrics.profile_visits??'—'}</td><td>${r.metrics.qualified_clicks??'—'}</td></tr>`).join('')||'<tr><td colspan="6">No deliveries recorded. Metrics become available after a simulation or manually recorded post.</td></tr>'}</tbody></table></div></div><p class="subtle">${esc(w.caveat)}</p>`;}
function comparison(a,dim){const rows=a.comparisons[dim];return `<div class="table-scroll"><table class="list-table"><thead><tr><th>${esc(dim)}</th><th>Posts</th><th>Meaningful replies / 1k impressions</th><th>Profile visits / 1k</th><th>Qualified clicks / 1k</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.value)}</td><td>${r.posts}</td>${['meaningful_replies','profile_visits','qualified_clicks'].map(k=>`<td>${r.rates[k].per_1000_impressions??'—'} <span class="subtle">(n=${r.rates[k].paired_posts})</span></td>`).join('')}</tr>`).join('')||'<tr><td colspan="5">No measurements in the comparable 24–48 hour observation window.</td></tr>'}</tbody></table></div>`;}
function openCampaignSetup(firstRun=false){
  const p=state.profile.profile,s=state.campaignSettings,b=s.browser||{},l=s.limits||{},pack=s.target_pack||{search_queries:[],groups:[]};
  const unique=values=>[...new Set(values)],packedAccounts=pack.groups.flatMap(group=>group.accounts);
  const queries=firstRun?unique([...(b.search_queries||[]),...pack.search_queries]):(b.search_queries||pack.search_queries);
  const accounts=firstRun?unique([...(b.watch_accounts||[]),...packedAccounts]):(b.watch_accounts||packedAccounts);
  state.setupFirstRun=firstRun;
  const groups=pack.groups.map(group=>`<div class="card"><strong>${esc(group.label)}</strong><p class="subtle">${group.accounts.map(account=>'@'+esc(account)).join(' · ')}</p></div>`).join('');
  const body=`<form id="campaign-setup-form">
    ${firstRun?'<div class="notice">Start in dry run. The first batch creates editable previews and never clicks Post.</div>':''}
    <div class="card"><h3>1. Your token</h3><div class="form-grid">${field('setup-name','Project name',p.name==='Your project'?'':p.name)}${field('setup-account','Your X account (without @)',p.account==='YourProject'?'':p.account)}${field('setup-ticker','Ticker',p.ticker==='TOKEN'?'':p.ticker)}${field('setup-chain','Chain',p.chain&&p.chain!=='Example Chain'?p.chain:'Cronos')}${field('setup-links','Official HTTPS links — one per line',p.official_links.join('\n'),'textarea',true)}${field('setup-disclosure','Short affiliation disclosure',p.disclosure,'text',true)}</div></div>
    <div class="card"><h3>2. Verified facts</h3><p class="subtle">Every generated reply uses one fact and its source. Add the contract only when you have an official source.</p><div class="form-grid">${field('setup-fact','One verified project fact',p.facts.find(f=>f.classification==='verified'&&f.id!=='verified-contract')?.text||'','textarea',true)}${field('setup-fact-source','Official source for that fact',p.facts.find(f=>f.classification==='verified'&&f.id!=='verified-contract')?.source||'','url',true)}${field('setup-contract','Verified contract address (optional)',p.contract_address)}${field('setup-contract-source','Official contract source (required if address is entered)',p.facts.find(f=>f.id===p.contract_fact_id)?.source||'','url')}</div></div>
    <div class="card"><h3>3. Cronos target pack</h3><p class="subtle">These are editable starting points. Account names can change, so check them in X before a live run.</p><div class="report-pair">${groups}</div><div class="form-grid">${field('setup-queries','Searches — one per line',queries.join('\n'),'textarea')}${field('setup-accounts','Accounts — one per line',accounts.join('\n'),'textarea')}${field('setup-keywords','Required relevance keywords — one per line',(p.keywords.length?p.keywords:['Cronos','CRO',p.ticker].filter(x=>x&&x!=='TOKEN')).join('\n'),'textarea')}${field('setup-blocked','Never reply to these accounts — one per line',(b.blocked_accounts||[]).join('\n'),'textarea')}</div></div>
    <div class="card"><h3>4. Pace and preview</h3><div class="form-grid">${field('setup-daily','Maximum replies per day',l.daily_post_limit??10,'number')}${field('setup-gap','Minimum minutes between replies',l.minimum_gap_minutes??60,'number')}${field('setup-cooldown','Days before replying to the same author again',b.author_cooldown_days??14,'number')}${field('setup-batch','Replies in each preview batch',b.preview_batch_size??10,'number')}${field('setup-score','Minimum relevance score (0–100)',b.minimum_score??35,'number')}${field('setup-poll','Minutes between discovery runs',b.poll_minutes??20,'number')}</div><label class="check-label"><input id="setup-dry-run" type="checkbox" ${firstRun||b.dry_run!==false?'checked':''} ${firstRun?'disabled':''}>Dry run: fill composers for inspection without clicking Post</label><label class="check-label"><input id="setup-autostart" type="checkbox" ${b.autostart?'checked':''}>Start the campaign worker when the dashboard starts</label><p class="field-note">The built-in template writer works without Ollama. You can switch writers later.</p></div>
  </form>`;
  utility(firstRun?'Set up your Cronos campaign':'Campaign settings',body,`<button class="primary" type="submit" form="campaign-setup-form">${firstRun?'Save safe setup':'Save campaign settings'}</button>`);
}
async function renderCampaign(){
  const b=await api('/browser');state.browser=b;
  if(!b.configured)return heading('Run a focused browser campaign.','Set mode = "browser" in config.toml and restart to use this workspace.','','LOCAL X SESSION')+empty('Browser mode is not configured','The manual and demo workflows remain available.');
  const c=b.counts||{},buttons=action('browser-preview-batch','Preview next batch','','small primary')+action('campaign-configure','Configure','','small')+action('browser-start','Start worker','','small')+action('browser-run-once','Run once','','small')+action('browser-stop-worker','Stop worker','','small')+action(b.stopped?'browser-resume':'browser-pause',b.stopped?'Resume campaign':'Pause campaign','','small')+action('browser-health','Check session','','small');
  const rows=(b.recent||[]).map(item=>{const p=item.post||{},editable=['queued','previewed','failed'].includes(item.state),requeue=['dismissed','failed'].includes(item.state);return `<article class="card campaign-item"><div class="card-top"><div><strong>@${esc(item.author)}</strong><br><small>${date(item.discovered_at)} · ${esc(item.generator||'not drafted')} · ${esc(item.style||'')}</small></div>${badge(item.state,item.state==='uncertain'?'red':item.state==='failed'?'amber':'')}</div><p class="post-text">${esc(p.text||'')}</p><a class="original-link" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">View target post ↗</a><div class="reason">${(item.ranking?.reasons||[]).map(esc).join(' · ')}</div>${item.draft_text?`<div class="preview space-top"><div class="eyebrow">CAMPAIGN REPLY</div><p class="post-text">${esc(item.draft_text)}</p></div>`:''}${item.error?`<div class="notice error">${esc(item.error)}</div>`:''}${item.diagnostic?`<a href="/api/browser/diagnostics/${encodeURIComponent(item.diagnostic)}" target="_blank">Open local failure screenshot ↗</a>`:''}<div class="card-footer"><span class="meta">Score ${esc(item.score)} · ${esc(p.replies||0)} replies · ${esc(p.likes||0)} likes${item.feedback?` · feedback ${item.feedback>0?'helpful':'poor fit'}`:''}</span><div class="button-row">${editable?action('browser-edit','Edit reply',`data-id="${esc(item.id)}"`,'small'):''}${editable?action('browser-dismiss','Dismiss',`data-id="${esc(item.id)}"`,'small'):''}${requeue?action('browser-requeue','Requeue',`data-id="${esc(item.id)}"`,'small'):''}${item.state==='sent'?action('browser-good','Helpful result',`data-id="${esc(item.id)}"`,'small')+action('browser-poor','Poor fit',`data-id="${esc(item.id)}"`,'small'):''}</div></div></article>`;}).join('');
  return heading('Operate the campaign from one place.','Discover, preview, edit, pause, and inspect browser replies.',buttons,'BROWSER CAMPAIGN')+`<div class="stats">${stat('Worker',b.running?'Running':'Stopped',b.last_run?'Last run '+date(b.last_run):'Not run in this process','◉')}${stat('Queued',c.queued||0,'Ranked opportunities','◎')}${stat('Previewed',c.previewed||0,b.dry_run?'No Post clicks':'Eligible for live run','✎')}${stat('Sent',c.sent||0,`Writer: ${esc(b.provider)}`,'↗')}</div>${b.last_error?`<div class="notice error">${esc(b.last_error)}</div>`:''}<div class="notice">${b.dry_run?'Dry run is enabled. Replies are filled into the composer for validation but Post is not clicked.':'Live browser posting is enabled.'} Threads are used once, authors have a cooldown, and ambiguous clicks activate the emergency stop.</div><div class="section-bar"><h2>Campaign queue <span class="subtle">/ ${(b.recent||[]).length}</span></h2>${action('refresh','↻ Refresh','','small')}</div>${rows||empty('The queue is empty','Run discovery after completing the project profile and browser login.')}`;
}

async function renderSystem(){const audit=await api('/audit'),h=state.health;return heading('A clear view behind the scenes.','Connection status, spending, and a durable record of every important action.',action('refresh','↻ Refresh','','small'),'OPERATIONS')+`<div class="report-pair"><div class="card"><h2>Integrations & API health</h2><div class="status-row"><span>X connection</span>${badge(h.mode==='browser'?'Local browser':'API unavailable',h.mode==='browser'?'':'amber')}</div><p class="subtle">${esc(h.x.detail)}</p><div class="status-row"><span>Model provider</span><strong>${esc(h.model.provider)}</strong></div><div class="status-row"><span>Model key</span><strong>${h.model.key_present?'Present (value hidden)':'Not configured; not needed for templates'}</strong></div><div class="status-row"><span>Scheduler</span>${badge(h.stopped?'Stopped':h.worker_running?'Running':'Not running',h.stopped?'red':'')}</div><div class="status-row"><span>Delivery behavior</span><strong>${esc(h.publishing)}</strong></div><div class="notice">The browser campaign is controlled from its dashboard page or the browser-* commands.</div></div><div class="card"><h2>Spending & limits</h2><div class="status-row"><span>Model: spent + reserved, rolling 24h</span><strong>$${h.model.reserved_or_spent_usd.toFixed(4)}</strong></div><div class="status-row"><span>Configured model budget</span><strong>$${Number(h.model.daily_budget_usd).toFixed(2)}</strong></div><div class="status-row"><span>X API spending</span><strong>$0 · no requests</strong></div><div class="status-row"><span>Post/attempt ceiling per rolling 24h</span><strong>${h.limits.daily}</strong></div><div class="status-row"><span>Minimum spacing</span><strong>${h.limits.gap_minutes} minutes</strong></div><div class="status-row"><span>Quiet hours · ${esc(h.timezone)}</span><strong>${h.limits.quiet_hours}</strong></div><p class="field-note">A failed/uncertain model call retains its reservation. Estimates depend on the prices you configure; provider billing is authoritative.</p></div></div><div class="card"><h2>Manual tools</h2><div class="button-row">${action('import','Import public conversations','','small')}${action('tag-link','Create a tagged official link','','small')}${action('seed-demo','Load fictional analytics examples','',state.health.mode==='demo'?'small':'hidden')}</div><p class="field-note">Import only data you are permitted to use. Browser mode has no DMs, challenge bypass, proxy rotation, or multi-account support.</p></div><div class="card"><h2>Audit log</h2><div class="table-scroll"><table class="list-table"><thead><tr><th>When</th><th>Action</th><th>Details</th></tr></thead><tbody>${audit.map(e=>`<tr><td class="nowrap">${date(e.at)}</td><td>${esc(e.action)}</td><td class="code">${esc(JSON.stringify(e.details))}</td></tr>`).join('')}</tbody></table></div></div>`;}
async function openEditor(id){const d=await api('/drafts/'+id);state.selected=d;const b=d.body,p=state.profile.profile,locked=['inflight','uncertain','simulated','posted','discarded'].includes(d.status);$('#editor-content').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">${esc(kinds[b.kind])} · VERSION ${d.revision}</span><h2>Make it sound like you.</h2></div>${action('close-editor','×','','close')}</div><div class="dialog-body"><div class="dialog-columns"><section><label for="draft-text">Content</label><textarea id="draft-text" class="editor-text" ${locked?'disabled':''}>${esc(b.text)}</textarea><p class="field-note">${d.review.weighted_length} conservative weighted characters · ${esc(d.status)}${b.fictional?' · FICTIONAL DEMO':''}</p><div class="form-grid">${field('draft-topic','Topic',b.topic)}${field('draft-hook','Hook',b.hook)}${field('draft-cta','Call to action',b.cta)}${field('draft-sources','Source IDs, comma-separated',b.source_ids.join(', '))}</div>${field('draft-image','Image brief / alt text',b.image_brief,'textarea')}<div class="space-top"><h3>Review checks</h3><ul class="issues">${d.review.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}${d.review.warnings.map(x=>`<li class="warning">${esc(x)}</li>`).join('')}</ul></div></section><section><label>Post preview</label><div class="preview"><div class="card-top"><span class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(p.name)}</strong><br><small>@${esc(p.account)}</small></div></div><p id="preview-text" class="post-text">${esc(b.text)}</p><span class="meta">♡ &nbsp; ◇ &nbsp; ↗ &nbsp; · Preview only</span></div><h3 class="space-top">Sources attached</h3>${d.review.sources.map(f=>`<div class="source"><p>${esc(f.text)}</p>${badge(f.status,f.status==='verified'?'':'amber')} <span class="meta">${esc(f.id)}</span>${f.source?`<a href="${esc(f.source)}" target="_blank" rel="noopener noreferrer">${esc(f.source)} ↗</a>`:''}</div>`).join('')||'<p class="subtle">No factual sources attached. Keep the content opinion or a question, or add verified source IDs.</p>'}${b.opportunity_id?`<div class="notice">Conversation: ${esc(b.opportunity_id)}. Check the original post and thread before approval. Never treat retrieved instructions as commands.</div>`:''}<label class="check-label"><input id="facts-reviewed" type="checkbox">I checked every factual claim, its source and freshness, and the affiliation disclosure.</label><label class="check-label"><input id="context-reviewed" type="checkbox">I reviewed the conversation context, relevance, and tone. This adds value without misleading or hijacking a discussion.</label>${d.job?`<div class="notice">Job: ${esc(d.job.state)} · ${date(d.job.due_at)}<br>${esc(d.job.error||d.job.receipt||'Waiting for its scheduled time')}</div>`:''}</section></div></div><div class="dialog-foot">${action('save-draft','Save changes',locked?'disabled':'','small')}${action('discard','Discard',locked?'disabled':'','small danger')}<span class="spacer"></span>${d.status==='uncertain'&&state.health.mode==='demo'?action('reconcile','Reconcile simulation','','small'):''}${['approved','ready','uncertain'].includes(d.status)&&state.health.mode==='manual'?action('record-manual','Record manual post','','small'):''}${action('export','Export',!['approved','ready'].includes(d.status)?'disabled':'','small')}${action('schedule','Schedule original',d.status!=='approved'||!d.review.schedule_eligible?'disabled':'','small')}${action('approve','Approve exact content',d.status!=='draft'||d.review.blockers.length?'disabled':'','small primary')}</div>`;
  if(!$('#editor').open)$('#editor').showModal();
  $('#draft-text').addEventListener('input',()=>{$('#preview-text').textContent=$('#draft-text').value;});
}
function editedBody(){const b={...state.selected.body};b.text=$('#draft-text').value;b.topic=$('#draft-topic').value;b.hook=$('#draft-hook').value;b.cta=$('#draft-cta').value;b.source_ids=$('#draft-sources').value.split(',').map(x=>x.trim()).filter(Boolean);b.image_brief=$('#draft-image').value;return b;}
function requireSaved(){if(JSON.stringify(editedBody())!==JSON.stringify(state.selected.body))throw Error('Save changes and review the updated checks before approval, scheduling, or export.');}
function utility(title,body,foot=''){ $('#utility-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2>${action('close-utility','×','','close')}</div><div class="dialog-body">${body}</div>${foot?`<div class="dialog-foot">${foot}</div>`:''}`;if(!$('#utility').open)$('#utility').showModal();}
function download(name,data){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function watchBrowser(){setTimeout(async()=>{try{await refresh();if(state.browser?.running)watchBrowser();}catch(e){toast(e.message,true);}},1000);}
async function actionHandler(el){const type=el.dataset.action,d=state.selected;
  if(type==='refresh')return refresh();
  if(type==='filter'){state.filter=el.dataset.filter;return render();}
  if(type==='close-editor')return $('#editor').close();
  if(type==='close-utility')return $('#utility').close();
  if(type==='stop'){await api('/stop','POST',{stopped:!state.health.stopped});toast(state.health.stopped?'Queue resumed.':'Emergency stop activated.');return refresh();}
  if(type==='campaign-configure')return openCampaignSetup(false);
  if(type==='browser-preview-batch'){const limit=state.campaignSettings?.browser?.preview_batch_size||10;await api('/browser/preview-batch','POST',{limit});toast(`Creating up to ${limit} editable previews in the background.`);watchBrowser();return refresh();}
  if(type==='browser-start'){await api('/browser/control','POST',{action:'start'});toast('Browser worker started.');return refresh();}
  if(type==='browser-stop-worker'){await api('/browser/control','POST',{action:'stop-worker'});toast('Browser worker stopped.');return refresh();}
  if(type==='browser-run-once'){await api('/browser/control','POST',{action:'run-once'});toast('Discovery run started in the background.');watchBrowser();return refresh();}
  if(type==='browser-pause'){await api('/browser/control','POST',{action:'pause'});toast('Campaign paused.');return refresh();}
  if(type==='browser-resume'){await api('/browser/control','POST',{action:'resume'});toast('Campaign resumed.');return refresh();}
  if(type==='browser-health'){const result=await api('/browser/session-health');toast(result.ok?'Browser session is ready.':'Browser session needs attention: '+result.state,!result.ok);return;}
  if(type==='browser-edit'){const item=state.browser.recent.find(x=>x.id===el.dataset.id);state.browserItem=item;return utility('Edit campaign reply',`<p class="subtle">The verified fact, official link, disclosure, length, and similarity checks still apply.</p><textarea id="browser-reply" class="export-text">${esc(item.draft_text||'')}</textarea>`,action('browser-save','Save reply','','primary'));}
  if(type==='browser-save'){await api('/browser/items/'+state.browserItem.id,'PUT',{text:$('#browser-reply').value});$('#utility').close();toast('Campaign reply saved.');return refresh();}
  if(type==='browser-dismiss'){await api('/browser/items/'+el.dataset.id+'/action','POST',{action:'dismiss'});toast('Opportunity dismissed.');return refresh();}
  if(type==='browser-requeue'){await api('/browser/items/'+el.dataset.id+'/action','POST',{action:'requeue'});toast('Opportunity returned to the queue.');return refresh();}
  if(type==='browser-good'||type==='browser-poor'){await api('/browser/items/'+el.dataset.id+'/feedback','POST',{value:type==='browser-good'?1:-1,note:''});toast('Campaign feedback saved for future ranking.');return refresh();}
  if(type==='suggest'){state.context={...state.opportunities.find(o=>o.id===el.dataset.id),kind:el.dataset.kind};location.hash='studio';if(state.view==='studio')await render();return;}
  if(type==='clear-context'){state.context=null;return render();}
  if(type==='edit')return openEditor(el.dataset.id);
  if(type==='new-draft'){const draft=await api('/drafts','POST',{text:'Add your idea here.\n\n'+state.profile.profile.disclosure,fictional:state.profile.profile.fictional});await refresh();return openEditor(draft.id);}
  if(type==='save-draft'){await api('/drafts/'+d.id,'PUT',{revision:d.revision,body:editedBody()});toast('Saved. Previous approval and schedule invalidated.');await refresh();return openEditor(d.id);}
  if(type==='approve'){requireSaved();await api('/drafts/'+d.id+'/approve','POST',{revision:d.revision,fingerprint:d.fingerprint,facts_reviewed:$('#facts-reviewed').checked,context_reviewed:$('#context-reviewed').checked});toast('This exact content is approved.');await refresh();return openEditor(d.id);}
  if(type==='discard'){await api('/drafts/'+d.id+'/discard','POST',{});$('#editor').close();toast('Draft discarded.');return refresh();}
  if(type==='schedule'){requireSaved();return utility('Choose a considered moment.',`<p class="subtle">${state.health.mode==='demo'?'This produces a fictional simulation, never an X post.':'This schedules a reminder/export-ready state; it does not publish to X.'} Quiet hours and posting limits may move the time later.</p>${field('schedule-time','Schedule in your browser timezone',dtInput(Date.now()/1000+300),'datetime-local')}`,action('confirm-schedule','Schedule this approved original','','primary'));}
  if(type==='confirm-schedule'){const due=new Date($('#schedule-time').value).getTime()/1000;if(!Number.isFinite(due))throw Error('Choose a valid date and time.');await api('/drafts/'+d.id+'/schedule','POST',{revision:d.revision,due_at:due});$('#utility').close();toast('Original scheduled.');await refresh();return openEditor(d.id);}
  if(type==='export'){requireSaved();const result=await api('/drafts/'+d.id+'/export','POST',{});state.exported=result;return utility('Your reviewed manual export',`<div class="notice warning">${esc(result.label)}</div><label for="export-content">Copy the content after one final review</label><textarea id="export-content" class="export-text" readonly>${esc(result.content.text)}</textarea>${result.content.image_brief?`<p class="subtle">Image brief: ${esc(result.content.image_brief)}</p>`:''}`,action('download-export','Download content + sources','','primary'));}
  if(type==='download-export')return download('reviewed-draft-'+d.id.slice(0,8)+'.json',state.exported);
  if(type==='record-manual'){return utility('Record a post you already sent.',`<p class="subtle">This records your confirmation, not an API-verified delivery. Do not send again if a result is uncertain; verify the account timeline first.</p>${field('receipt-url','X post URL from your project account','','url')}`,action('confirm-manual','Record confirmed post','','primary'));}
  if(type==='confirm-manual'){await api('/drafts/'+d.id+'/record-manual','POST',{post_url:$('#receipt-url').value});$('#utility').close();await refresh();return openEditor(d.id);}
  if(type==='reconcile'){await api('/drafts/'+d.id+'/reconcile-demo','POST',{});toast('Confirmed simulation receipt recovered.');await refresh();return openEditor(d.id);}
  if(type==='add-fact'){const i=Date.now();$('#facts').insertAdjacentHTML('beforeend',factForm({id:'source-'+i,text:'',source:'',classification:'unverified',stale_after_days:30},i));return;}
  if(type==='remove-fact'){el.closest('.fact').remove();return;}
  if(type==='comparison'){$('#comparison-table').innerHTML=comparison(state.analytics,el.dataset.dimension);return;}
  if(type==='weekly-export')return download('weekly-report.json',state.analytics.weekly);
  if(type==='import'){const sample={opportunities:[{id:'manual-001',author:'ProjectReader',text:'What would make a community roadmap easier to understand?',url:'https://x.com/ProjectReader/status/1234567890',posted_at:Math.floor(Date.now()/1000),thread_id:'1234567890',context:'Replace with real context. Read the original thread.',inbound:false,replies:0,likes:0,fictional:true}]};return utility('Import permitted conversation data',`<p class="subtle">Paste a JSON batch of up to 100 public posts you are permitted to use. The example below is fictional. Existing IDs are immutable to preserve approval context.</p><textarea id="import-json" class="export-text code">${esc(JSON.stringify(sample,null,2))}</textarea>`,action('confirm-import','Import conversations','','primary'));}
  if(type==='confirm-import'){const payload=JSON.parse($('#import-json').value);await api('/opportunities/import','POST',payload);$('#utility').close();toast('Conversations imported and ranked.');return refresh();}
  if(type==='tag-link')return utility('Make clicks easier to understand.',`${field('tag-url','Official HTTPS URL','','url')}${field('tag-campaign','Campaign name','community-learning')}${field('tag-content','Content/experiment label','question-hook')}<p class="field-note">Tagged clicks do not establish token purchases or price effects.</p>`,action('confirm-tag','Create tagged link','','primary'));
  if(type==='confirm-tag'){const r=await api('/tag-link','POST',{url:$('#tag-url').value,campaign:$('#tag-campaign').value,content:$('#tag-content').value});return utility('Your tagged link',`<textarea readonly>${esc(r.url)}</textarea>`);}
  if(type==='seed-demo'){await api('/demo/analytics','POST',{});toast('Fictional measurements added. No X calls made.');return refresh();}
  if(type==='metrics'){const posts=(state.analytics?.posts||[]);if(!posts.length)throw Error('First simulate a scheduled original or record a real manual post.');return utility('Record available measurements',`<form id="metrics-form"><label for="metrics-draft">Delivered post</label><select id="metrics-draft">${posts.map(p=>`<option value="${p.id}">${esc(p.body.topic)} · ${p.id.slice(0,8)} · ${esc(p.mode)}</option>`).join('')}</select>${field('metrics-time','Captured at',dtInput(Date.now()/1000),'datetime-local')}<div class="form-grid space-top">${['impressions','likes','replies','meaningful_replies','reposts','profile_visits','clicks','qualified_clicks'].map(k=>field('metric-'+k,k.replaceAll('_',' ')+' (blank = unavailable)','','number')).join('')}</div>${field('metrics-source','Source / qualification rule','Manual analytics observation')}<button class="primary space-top" type="submit">Save measurements</button></form>`);}
}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;event.preventDefault();button.disabled=true;try{await actionHandler(button);}catch(e){toast(e.message,true);}finally{button.disabled=false;}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,submit=$('[type=submit]',form);if(submit)submit.disabled=true;try{
  if(form.id==='campaign-setup-form'){
    const value=id=>$('#'+id).value.trim(),now=Date.now()/1000,account=value('setup-account').replace(/^@/,'');
    const required=[['setup-name','project name'],['setup-account','X account'],['setup-fact','verified fact'],['setup-fact-source','fact source'],['setup-links','official link'],['setup-disclosure','affiliation disclosure']];
    const missing=required.filter(([id])=>!value(id)).map(([,label])=>label);if(missing.length)throw Error('Add the '+missing.join(', ')+'.');
    if(value('setup-contract')&&!value('setup-contract-source'))throw Error('Add the official source for the contract address.');
    const p={...state.profile.profile,name:value('setup-name'),account,ticker:value('setup-ticker'),chain:value('setup-chain'),contract_address:value('setup-contract'),official_links:list($('#setup-links').value),disclosure:value('setup-disclosure'),keywords:list($('#setup-keywords').value),monitored_accounts:list($('#setup-accounts').value).map(x=>x.replace(/^@/,'')),fictional:false};
    p.facts=[{id:'project-overview',text:value('setup-fact'),source:value('setup-fact-source'),classification:'verified',verified_at:now,stale_after_days:30}];
    if(p.contract_address){p.contract_fact_id='verified-contract';p.facts.push({id:'verified-contract',text:`The verified contract address for ${p.name} is ${p.contract_address}.`,source:value('setup-contract-source'),classification:'verified',verified_at:now,stale_after_days:30});}else p.contract_fact_id='';
    await api('/profile','PUT',{profile:p,version:state.profile.version});
    const browser={...(state.campaignSettings.browser||{}),dry_run:state.setupFirstRun?true:$('#setup-dry-run').checked,search_queries:list($('#setup-queries').value),watch_accounts:p.monitored_accounts,blocked_accounts:list($('#setup-blocked').value).map(x=>x.replace(/^@/,'')),minimum_score:Number($('#setup-score').value),author_cooldown_days:Number($('#setup-cooldown').value),preview_batch_size:Number($('#setup-batch').value),poll_minutes:Number($('#setup-poll').value),autostart:$('#setup-autostart').checked};
    const limits={...(state.campaignSettings.limits||{}),daily_post_limit:Number($('#setup-daily').value),minimum_gap_minutes:Number($('#setup-gap').value)};
    await api('/campaign-settings','PUT',{version:state.campaignSettings.version,browser,limits,onboarding_complete:true});
    $('#utility').close();state.onboardingShown=true;toast('Campaign setup saved. Use Preview next batch after you sign in to X.');await refresh();
  }
  if(form.id==='generator'){const data=new FormData(form);await api('/generate','POST',{kind:data.get('kind'),tone:data.get('tone'),topic:data.get('topic'),opportunity_id:state.context?.id||null});toast('Three options created. Check the sources and make them yours.');await refresh();}
  if(form.id==='knowledge-form'){const p={...state.profile.profile},data=new FormData(form);for(const k of ['name','account','ticker','chain','contract_address','contract_fact_id','audience','voice','disclosure'])p[k]=data.get(k);for(const k of ['official_links','slang','jokes','competitors','keywords','monitored_accounts','forbidden_claims','good_examples','bad_examples'])p[k]=list(data.get(k));p.fictional=$('#fictional').checked;p.facts=$$('[data-fact]').map(el=>{const i=el.dataset.fact,t=$('#fact-time-'+i).value;return {id:$('#fact-id-'+i).value,text:$('#fact-text-'+i).value,source:$('#fact-source-'+i).value,classification:$('#fact-class-'+i).value,stale_after_days:Number($('#fact-days-'+i).value),verified_at:t?new Date(t).getTime()/1000:null};});await api('/profile','PUT',{profile:p,version:state.profile.version});toast('Project knowledge saved. Pending approvals invalidated.');await refresh();}
  if(form.id==='metrics-form'){const m={captured_at:new Date($('#metrics-time').value).getTime()/1000,source:$('#metrics-source').value};for(const k of ['impressions','likes','replies','meaningful_replies','reposts','profile_visits','clicks','qualified_clicks']){const v=$('#metric-'+k).value;m[k]=v===''?null:Number(v);}await api('/drafts/'+$('#metrics-draft').value+'/metrics','POST',m);$('#utility').close();toast('Metrics recorded; blank values remain unavailable.');await refresh();}
}catch(e){toast(e.message,true);}finally{if(submit)submit.disabled=false;}});
async function navigate(){state.view=titles[location.hash.slice(1)]?location.hash.slice(1):'opportunities';try{if(!state.health)await refresh();else{updateShell();await render();}}catch(e){toast(e.message,true);}}
window.addEventListener('hashchange',navigate);
